   152	Object Lexer::getObj(int objNum) {
   153	  char *p;
   154	  int c, c2;
   155	  bool comment, neg, done, overflownInteger, overflownLongLong;
   156	  int numParen;
   157	  int xi;
   158	  long long xll = 0;
   159	  double xf = 0, scale;
   160	  GooString *s;
   161	  int n, m;
   162	
   163	  // skip whitespace and comments
   164	  comment = false;
   165	  while (1) {
   166	    if ((c = getChar()) == EOF) {
   167	      return Object(objEOF);
   168	    }
   169	    if (comment) {
   170	      if (c == '\r' || c == '\n')
   171	        comment = false;
   172	    } else if (c == '%') {
   173	      comment = true;
   174	    } else if (specialChars[c] != 1) {
   175	      break;
   176	    }
   177	  }
   178	
   179	  // start reading token
   180	  switch (c) {
   181	
   182	  // number
   183	  case '0': case '1': case '2': case '3': case '4':
   184	  case '5': case '6': case '7': case '8': case '9':
   185	  case '+': case '-': case '.':
   186	    overflownInteger = false;
   187	    overflownLongLong = false;
   188	    neg = false;
   189	    xi = 0;
   190	    if (c == '-') {
   191	      neg = true;
   192	    } else if (c == '.') {
   193	      goto doReal;
   194	    } else if (c != '+') {
   195	      xi = c - '0';
   196	    }
   197	    while (1) {
   198	      c = lookChar();
