   247	    if (likely(!overflownInteger)) {
   248	      xf = xi;
   249	    } else if (!overflownLongLong) {
   250	      xf = xll;
   251	    }
   252	    scale = 0.1;
   253	    while (1) {
   254	      c = lookChar();
   255	      if (c == '-') {
   256	        // ignore minus signs in the middle of numbers to match
   257	        // Adobe's behavior
   258	        error(errSyntaxWarning, getPos(), "Badly formatted number");
   259	        getChar();
   260	        continue;
   261	      }
   262	      if (!isdigit(c)) {
   263	        break;
   264	      }
   265	      getChar();
   266	      xf = xf + scale * (c - '0');
   267	      scale *= 0.1;
   268	    }
   269	    if (neg) {
   270	      xf = -xf;
   271	    }
   272	    return Object(xf);
   273	    break;
   274	
   275	  // string
   276	  case '(':
   277	    p = tokBuf;
   278	    n = 0;
   279	    numParen = 1;
   280	    done = false;
   281	    s = nullptr;
   282	    do {
   283	      c2 = EOF;
   284	      switch (c = getChar()) {
   285	
   286	      case EOF:
   287	#if 0
   288	      // This breaks some PDF files, e.g., ones from Photoshop.
   289	      case '\r':
   290	      case '\n':
   291	#endif
   292	        error(errSyntaxError, getPos(), "Unterminated string");
   293	        done = true;
   294	        break;
   295	
   296	      case '(':
   297	        ++numParen;
   298	        c2 = c;
   299	        break;
   300	
   301	      case ')':
