   304	        } else {
   305	          c2 = c;
   306	        }
   307	        break;
   308	
   309	      case '\\':
   310	        switch (c = getChar()) {
   311	        case 'n':
   312	          c2 = '\n';
   313	          break;
   314	        case 'r':
   315	          c2 = '\r';
   316	          break;
   317	        case 't':
   318	          c2 = '\t';
   319	          break;
   320	        case 'b':
   321	          c2 = '\b';
   322	          break;
   323	        case 'f':
   324	          c2 = '\f';
   325	          break;
   326	        case '\\':
   327	        case '(':
   328	        case ')':
