   446	        s = new GooString(tokBuf, n);
   447	      } else {
   448	        s->append((char)c);
   449	      }
   450	    }
   451	    if (n < tokBufSize) {
   452	      *p = '\0';
   453	      return Object(objName, tokBuf);
   454	    } else {
