   492	          break;
   493	        } else if (specialChars[c] != 1) {
   494	          c2 = c2 << 4;
   495	          if (c >= '0' && c <= '9')
   496	            c2 += c - '0';
   497	          else if (c >= 'A' && c <= 'F')
   498	            c2 += c - 'A' + 10;
   499	          else if (c >= 'a' && c <= 'f')
   500	            c2 += c - 'a' + 10;
