   526	    }
   527	    break;
   528	
   529	  // dict punctuation
   530	  case '>':
   531	    c = lookChar();
   532	    if (c == '>') {
   533	      getChar();
   534	      tokBuf[0] = tokBuf[1] = '>';
   535	      tokBuf[2] = '\0';
   536	      return Object(objCmd, tokBuf);
   537	    } else {
   538	      error(errSyntaxError, getPos(), "Illegal character '>'");
   539	      return Object(objError);
   540	    }
   541	    break;
   542	
   543	  // error
   544	  case ')':
   545	  case '{':
   546	  case '}':
   547	    error(errSyntaxError, getPos(), "Illegal character '{0:c}'", c);
   548	    return Object(objError);
   549	    break;
   550	
   551	  // command
   552	  default:
   553	    p = tokBuf;
   554	    *p++ = c;
   555	    n = 1;
   556	    while ((c = lookChar()) != EOF && !specialChars[c]) {
   557	      getChar();
   558	      if (++n == tokBufSize) {
   559	        error(errSyntaxError, getPos(), "Command token too long");
