   621	void Lexer::skipToNextLine() {
   622	  int c;
   623	
   624	  while (1) {
   625	    c = getChar();
   626	    if (c == EOF || c == '\n') {
   627	      return;
   628	    }
   629	    if (c == '\r') {
   630	      if ((c = lookChar()) == '\n') {
   631	        getChar();
   632	      }
   633	      return;
   634	    }
   635	  }
